    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    parse,
)

__all__ = [
    "Entry",
    "ParseError",
    "parse",
    "balance",
    "by_category",
    "by_month",
    "filter_entries",
]
import sys

from .cli import main

if __name__ == "__main__":
    sys.exit(main())

